  const w2y = Math.cos(sy*0.022+t*0.45)*7 + Math.sin(sx*0.028-t*0.3)*9;
  const dx = sx+w2x, dy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.5)*110, 70+Math.cos(t*0.35)*55, 0.07, 2.1, 0.9],
    [320+Math.cos(t*0.45)*100, 170+Math.sin(t*0.6)*60, 0.09, 1.8, 1.1],
    [240+Math.sin(t*0.28+2)*150, 110+Math.cos(t*0.42+1)*95, 0.055, 2.4, 0.7],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.5+3)*65, 0.11, 1.6, 1.2],
    [380+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.8+2)*75, 0.065, 2.7, 0.8],
    [240+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.5)*85, 0.085, 2.0, 1.0],
    [60+Math.sin(t*0.55+3)*70, 40+Math.cos(t*0.65+1)*50, 0.1, 1.9, 1.15],
    [420+Math.cos(t*0.4+2)*80, 130+Math.sin(t*0.75)*55, 0.075, 2.2, 0.85]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((dx-sX)**2 + (dy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.65 + t*sp*0.55 + 1.7) * w;
    cS += Math.sin(d*f*1.3 - t*sp*0.8 + 2.5) * w * 0.5;
  }
  const aN=aS/6.6, iN=iS/6.6, cN=cS/4.2;
  const bg1 = (Math.sin(dx*0.035+dy*0.022+t*0.7) + Math.sin(dx*0.028-dy*0.038+t*1.05))/2;
  const bg2 = Math.sin((dx+dy)*0.11+t*2.2)*0.25 + Math.sin((dx-dy)*0.09-t*1.8)*0.25;
  const bg3 = Math.sin(dx*0.06+dy*0.045-t*1.3)*0.15 + Math.cos(dx*0.04-dy*0.055+t*0.9)*0.15;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((dx-cx)**2 + (dy-cy)**2), ang = Math.atan2(dy-cy, dx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.4) + Math.sin(dist*0.035+ang*4.5-t*1.1);
