  const organic = Math.tanh(lap*1.2)*0.35;
  const rd1 = Math.tanh((aN - iN*0.65 + bg*0.25 + spiral*0.3)*2.0);
  const rd2 = Math.tanh((cN - aN*0.4 + iN*0.3 - bg*0.2 + organic)*1.8);
  const coupled = Math.tanh((rd1*1.2 + rd2*0.8 + organic*0.5)*1.6);
  const detail = Math.sin(dx*0.2+dy*0.15+t*3)*Math.sin(dx*0.18-dy*0.22-t*2.5)*0.15;
  const final = coupled*0.82 + detail + organic*0.15;
  const v = Math.tanh(final)*0.5+0.5;
  const pal = [
    [5,12,52],[10,45,85],[12,85,105],[18,135,120],[45,165,100],
    [140,185,65],[210,190,50],[235,155,55],[225,110,65],[185,65,60],
    [130,35,55],[70,18,52],[30,12,48],[5,12,52]
  ];
